def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key or not eight:
        return out

    # The colored key and the 8-pattern are both polyominoes of equal
    # numbers of tiles. Match their tile layouts under rotation/reflection.
    def components(cells):
        unseen = set(cells)
        result = []
        while unseen:
            start = unseen.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in unseen:
                        unseen.remove(p)
                        comp.add(p)
                        stack.append(p)
            result.append(comp)
        return result

    # Tile side inferred from the key marks and the regular repeated blocks.
    # Key cells occupy one pixel per tile; large tile size is 4 in this task.
    size = 4
    key_tiles = {(r, c): v for r, c, v in key}
    kr0, kc0 = min(r for r,c in key_tiles), min(c for r,c in key_tiles)
    key_tiles = {(r-kr0, c-kc0): v for (r,c),v in key_tiles.items()}

    tile_set = {(r//size, c//size) for r,c in eight}
    tr0, tc0 = min(r for r,c in tile_set), min(c for r,c in tile_set)
    tile_set = {(r-tr0,c-tc0) for r,c in tile_set}

    def variants(mapping):
        ans = []
        for reflect in (False, True):
            for rot in range(4):
                d = {}
                for (r,c),v in mapping.items():
                    if reflect:
                        c = -c
                    for _ in range(rot):
                        r,c = c,-r
                    d[(r,c)] = v
                mr = min(r for r,c in d)
                mc = min(c for r,c in d)
                ans.append({(r-mr,c-mc):v for (r,c),v in d.items()})
        return ans

    chosen = None
    for d in variants(key_tiles):
        if set(d) == tile_set:
            chosen = d
            break
    if chosen is None:
        chosen = variants(key_tiles)[0]

    for r,c in eight:
        tile = (r//size-tr0, c//size-tc0)
        if tile in chosen:
            out[r][c] = chosen[tile]
    return out
